// Lineart assets generated by /artgen (see artgen/README.md). Served from public/art as SVG.
import type { ImgHTMLAttributes } from 'react';

type Img = Omit<ImgHTMLAttributes<HTMLImageElement>, 'src'>;

const art = (path: string) => `/art/${path}.svg`;

export const PLANT_TYPES = ['coal', 'oil', 'garbage', 'uranium', 'hybrid', 'wind', 'solar'] as const;
export type PlantType = (typeof PLANT_TYPES)[number];

const normalizeType = (t: string): PlantType => {
  const lower = t.toLowerCase();
  if (lower === 'eco') return 'wind';
  return (PLANT_TYPES as readonly string[]).includes(lower) ? (lower as PlantType) : 'coal';
};

/** Illustrated power plant card (180×120 base). Falls back to the type template. */
export function PlantCard({ type, number, ...rest }: Img & { type: string; number: number }) {
  const t = normalizeType(type);
  return (
    <img
      src={art(`game/power_plants/power_plant_${t}_${number}`)}
      onError={(e) => {
        (e.currentTarget as HTMLImageElement).src = art(`game/power_plants/card_template_${t}`);
      }}
      alt={`Power plant ${number} (${t})`}
      width={180}
      height={120}
      draggable={false}
      {...rest}
    />
  );
}

export function ResourceIcon({ type, size = 32, ...rest }: Img & { type: string; size?: number }) {
  return <img src={art(`game/resources/resource_${normalizeType(type)}`)} alt={type} width={size} height={size} draggable={false} {...rest} />;
}

export function PlayerHouse({ color, size = 24, ...rest }: Img & { color: string; size?: number }) {
  return <img src={art(`players/colors/flag_${color.toLowerCase()}`)} alt={`${color} house`} width={size} height={size} draggable={false} {...rest} />;
}

export function CityMarker({ color = 'brown', size = 30, ...rest }: Img & { color?: string; size?: number }) {
  return <img src={art(`game/cities/city_${color}`)} alt="city" width={size} height={size} draggable={false} {...rest} />;
}

export function PhaseBadge({ phase, size = 48, ...rest }: Img & { phase: 'auction' | 'resource' | 'building' | 'bureaucracy'; size?: number }) {
  const file = phase === 'resource' ? 'phase_resources' : `phase_${phase}`;
  return <img src={art(`ui/phases/${file}`)} alt={phase} width={size} height={size} draggable={false} {...rest} />;
}

export function Logo(props: Img) {
  return <img src={art('ui/branding/logo')} alt="Power Grid" width={600} height={150} draggable={false} {...props} />;
}

/** Tailwind-friendly ink style tokens matching artgen/style.mjs. */
